const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envFile = fs.readFileSync('./.env.test', 'utf8');

// Parse environment variables (skip comments)
const envVars = {};
const lines = envFile.split('\n');
lines.forEach(line => {
  // Skip comments and empty lines
  if (line.trim() && !line.trim().startsWith('#')) {
    const [key, value] = line.split('=');
    if (key && value) {
      envVars[key.trim()] = value.trim();
    }
  }
});

// Convert to JSON
const jsonData = JSON.stringify(envVars, null, 2);

console.log('Environment variables JSON:');
console.log(jsonData);

// POST to the API endpoint
const postData = JSON.stringify(envVars);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log('Status code:', res.statusCode);
  res.setEncoding('utf8');
  let responseBody = '';
  res.on('data', (chunk) => {
    responseBody += chunk;
  });
  res.on('end', () => {
    console.log('Successfully posted environment variables to documentation wiki');
    console.log('Response:', responseBody);
  });
});

req.on('error', (error) => {
  console.error('Error posting to documentation wiki:', error.message);
});

req.write(postData);
req.end();
"

