const fs = require('fs');
const axios = require('axios');
const envFile = '.env.test';
const envData = fs.readFileSync(envFile, 'utf8');

// Parse .env file into key-value pairs
const envVariables = {};
envData.split('\n').forEach(line => {
  const match = line.match(/^(\\w+)=(.+)$/);
  if (match) {
    const key = match[1];
    const value = match[2];
    envVariables[key] = value;
  }
});

axios.post('http://localhost:47301/api/doc-export', envVariables)
  .then(response => {
    console.log('Successfully exported environment variables:', response.data);
  })
  .catch(error => {
    console.error('Failed to export environment variables:', error.response ? error.response.data : error.message);
  });
"

